// Config plugin: signs release builds with YOUR upload keystore instead of the shared debug key.
//
// The android/ folder is generated by `npx expo prebuild`, so it must not be edited by hand.
// This plugin makes the change every time android/ is generated.
//
// The keystore location and passwords are read from Gradle properties, normally kept in
// %USERPROFILE%\.gradle\gradle.properties (outside the project, never committed):
//   CRICKET_UPLOAD_STORE_FILE, CRICKET_UPLOAD_STORE_PASSWORD,
//   CRICKET_UPLOAD_KEY_ALIAS, CRICKET_UPLOAD_KEY_PASSWORD
// A release build stops with a clear message if they are missing, because an APK signed with a
// different key cannot update an installed one: Android would force an uninstall, which deletes
// all match data on the phone. See docs/ANDROID_BUILD.md.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = 'CRICKET_UPLOAD_STORE_FILE';

const RELEASE_SIGNING_CONFIG = `
        release {
            // Added by plugins/withReleaseSigning.js
            if (project.hasProperty('CRICKET_UPLOAD_STORE_FILE')) {
                storeFile file(project.property('CRICKET_UPLOAD_STORE_FILE'))
                storePassword project.property('CRICKET_UPLOAD_STORE_PASSWORD')
                keyAlias project.property('CRICKET_UPLOAD_KEY_ALIAS')
                keyPassword project.property('CRICKET_UPLOAD_KEY_PASSWORD')
            }
        }`;

const MISSING_KEYSTORE_CHECK = `

// Added by plugins/withReleaseSigning.js: refuse to build an unsigned or debug-signed release.
gradle.taskGraph.whenReady { graph ->
    def buildsRelease = graph.allTasks.any { it.project == project && it.name ==~ /(package|bundle)Release/ }
    if (buildsRelease && !project.hasProperty('CRICKET_UPLOAD_STORE_FILE')) {
        throw new GradleException("Release signing is not set up. Add CRICKET_UPLOAD_STORE_FILE, " +
            "CRICKET_UPLOAD_STORE_PASSWORD, CRICKET_UPLOAD_KEY_ALIAS and CRICKET_UPLOAD_KEY_PASSWORD " +
            "to your user gradle.properties. See docs/ANDROID_BUILD.md.")
    }
}
`;

function replaceOnce(contents, pattern, replacement, what) {
  if (!pattern.test(contents)) {
    throw new Error(
      `withReleaseSigning: could not find ${what} in android/app/build.gradle. ` +
        'The Expo template may have changed; update plugins/withReleaseSigning.js.',
    );
  }
  return contents.replace(pattern, replacement);
}

function addReleaseSigning(contents) {
  if (contents.includes(MARKER)) return contents; // already applied
  // 1) The release build type uses the release signing config instead of the debug one.
  contents = replaceOnce(
    contents,
    /(buildTypes\s*\{[\s\S]*?release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
    '$1signingConfig signingConfigs.release',
    'the release build type',
  );
  // 2) Define the release signing config right after the debug one.
  contents = replaceOnce(
    contents,
    /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/,
    `$1${RELEASE_SIGNING_CONFIG}`,
    'the debug signing config',
  );
  return contents + MISSING_KEYSTORE_CHECK;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning: expected a Groovy build.gradle.');
    }
    cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.addReleaseSigning = addReleaseSigning;
